  deleted_at ISNULL AND
  id IN (6,7,16,31,33,79,131,159,176,185,202,238,265,288,295,391,507,508,549,551,610,613,615,701,710,749,786,827,933,986,994,997,998,1035,1039,1059,1078,1086,1098,1127,1134,1146,1190,1205,1254,1300,1301,1332,1334,1338,1348,1463,1516,1527,1528,1529,1618,1631,1634,1635,1656,1658,1750,1882,1948,2641,3565,3961,4192,4258,4390,5710,5809,5811,6205,6206,6207,6208,6436,6469,6865,7426,9010,9109,9142,9241,9242,9637,9638,9739,9802,10235,10264,10602,10627,10628,10660,11089,11090,11091,11353,12379,12380,13069,13103)
